function validate([windows, queries]) {
  const n = windows.length;
  if (n < 1 || n > 100000) return 'windows needs 1 to 10^5 entries.';
  const seen = new Array(n + 1).fill(false);
  for (const id of windows) {
    if (id < 1 || id > n || seen[id]) return 'windows must contain each label from 1 to n exactly once.';
    seen[id] = true;
  }
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  if (queries.some(id => id < 1 || id > n)) return 'Each query names a window label from 1 to n.';
  return null;
}

