function simulationResult(windows, queries) {
  const placed = new Set();
  const result = [];
  for (let i = queries.length - 1; i >= 0; i--) {
    const id = queries[i];
    if (!placed.has(id)) {
      placed.add(id);
      result.push(id);
    }
  }
  for (const id of windows) {
    if (!placed.has(id)) {
      result.push(id);
    }
  }
  return result;
}

