function simulationResult(windows, queries) {
  // Move each queried window to the front of the array, one query at a time.
  const stack = windows.slice();
  for (const query of queries) {
    const at = stack.indexOf(query);
    stack.splice(at, 1);
    stack.unshift(query);
  }
  return stack;
}

