function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(1500, 2000) : int(1, 6);
  const windows = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = int(0, i);
    [windows[i], windows[j]] = [windows[j], windows[i]];
  }
  // Half the time the queries use only a few labels, so many windows never move and repeats are common.
  const pool = rand() < 0.5 ? n : int(1, Math.min(n, large ? 60 : 3));
  const q = large ? int(1500, 2000) : int(1, 8);
  const queries = Array.from({ length: q }, () => int(1, pool));
  return [windows, queries];
}
